mapper.select:
SELECT id, token_hash, user_id, family_id, status, issued_at, expires_at, revoked_at,
       replaced_by_hash, client_fingerprint_hash, created_at, updated_at
FROM refresh_token WHERE token_hash = #{tokenHash}

mapper.update:
UPDATE refresh_token
SET status = 'ROTATED', revoked_at = #{now}, replaced_by_hash = #{replacedByHash}, updated_at = #{now}
WHERE id = #{id} AND status = 'ACTIVE'

UPDATE refresh_token
SET status = 'REVOKED', revoked_at = COALESCE(revoked_at, #{now}), updated_at = #{now}
WHERE family_id = #{familyId} AND status IN ('ACTIVE', 'ROTATED')

UPDATE refresh_token
SET status = 'REVOKED', revoked_at = #{now}, updated_at = #{now}
WHERE user_id = #{userId} AND status = 'ACTIVE'
